```kotlin
@Service
class RedisMessageBroker(
    private val reactiveRedisTemplate: ReactiveRedisTemplate<String, String>,
    private val objectMapper: ObjectMapper
) {

    fun publishMessage(roomId: Long, message: WebSocketMessage): Mono<Long> {
        val channel = "chat:room:$roomId"
        val messageJson = objectMapper.writeValueAsString(message)
        return reactiveRedisTemplate.convertAndSend(channel, messageJson)
    }

    fun subscribeToRoom(roomId: Long): Flux<WebSocketMessage> {
        val channel = "chat:room:$roomId"
        return reactiveRedisTemplate.listenTo(ChannelTopic.of(channel))
            .map { objectMapper.readValue(it.message, WebSocketMessage::class.java) }
    }
}
```

