@Component
class ChatWebSocketHandler(
    private val messageService: MessageService,
    private val redisMessageBroker: RedisMessageBroker,
    private val jwtTokenProvider: JwtTokenProvider
) : WebSocketHandler {

    private val sessions = ConcurrentHashMap<String, WebSocketSession>()
    private val roomSessions = ConcurrentHashMap<Long, MutableSet<String>>()

    override fun handle(session: WebSocketSession): Mono<Void> {
        return session.receive()
            .map { it.payloadAsText }
            .map { objectMapper.readValue(it, WebSocketMessage::class.java) }
            .flatMap { handleMessage(session, it) }
            .doOnError { handleError(session, it) }
            .then()
    }

    private fun handleMessage(session: WebSocketSession, message: WebSocketMessage): Mono<Void> {
        return when (message.type) {
            MessageType.CHAT -> handleChatMessage(session, message)
            MessageType.JOIN -> handleJoinRoom(session, message)
            MessageType.LEAVE -> handleLeaveRoom(session, message)
            MessageType.TYPING -> handleTypingIndicator(session, message)
        }
    }
}
```

