@Component
class GlobalExceptionHandler : WebExceptionHandler {

    override fun handle(exchange: ServerWebExchange, ex: Throwable): Mono<Void> {
        return when (ex) {
            is AuthenticationException -> handleAuthError(exchange, ex)
            is ValidationException -> handleValidationError(exchange, ex)
            is WebSocketException -> handleWebSocketError(exchange, ex)
            else -> handleGenericError(exchange, ex)
        }
    }
}

@Configuration
@EnableConfigurationProperties(CacheProperties::class)
class CacheConfig {

    @Bean
    fun cacheManager(): RedisCacheManager {
        return RedisCacheManager.builder()
            .cacheDefaults(cacheConfiguration())
            .transactionAware()
            .build()
    }

    private fun cacheConfiguration(): RedisCacheConfiguration {
        return RedisCacheConfiguration.defaultCacheConfig()
            .entryTtl(Duration.ofMinutes(10))
            .serializeKeysWith(RedisSerializationContext.SerializationPair.fromSerializer(StringRedisSerializer()))
            .serializeValuesWith(RedisSerializationContext.SerializationPair.fromSerializer(GenericJackson2JsonRedisSerializer()))
    }
}
